package com.zheng.algorithm.leetcode;

import com.zheng.algorithm.leetcode.tree.TreeNode;

/**
 * @author zheng
 * @date 2020/12/14
 */
public class LeetCode100 {

    public boolean isSameTree(TreeNode p, TreeNode q) {
        if (p == null && q == null) {
            return true;
        }
        if (p == null || q == null) {
            return false;
        }
        if (p.val != q.val) {
            return false;
        }
        return isSameTree(p.left, q.left) && isSameTree(p.right, q.right);
    }
}
